{
  "apiVersion": 1,
  "type": "component.detail.props",
  "package": "@astryxdesign/core",
  "data": [
    {
      "name": "label",
      "type": "string",
      "description": "Label text for the checkbox group (always rendered for accessibility).",
      "required": true
    },
    {
      "name": "children",
      "type": "ReactNode",
      "description": "CheckboxListItem elements.",
      "slotElements": [
        {
          "__element": "CheckboxListItem",
          "props": {
            "label": "Option",
            "value": "option"
          }
        }
      ],
      "required": true
    },
    {
      "name": "value",
      "type": "string[]",
      "description": "The currently selected values (collection mode)."
    },
    {
      "name": "onChange",
      "type": "(values: string[]) => void",
      "description": "Callback fired when the selected values change."
    },
    {
      "name": "changeAction",
      "type": "(values: string[]) => void | Promise<void>",
      "description": "Async action on change with optimistic updates. While the promise is pending, the toggled item shows a spinner inside its checkbox and is marked aria-busy."
    },
    {
      "name": "isLabelHidden",
      "type": "boolean",
      "description": "Whether to visually hide the label.",
      "default": "false"
    },
    {
      "name": "description",
      "type": "string",
      "description": "Description text displayed below the label."
    },
    {
      "name": "isOptional",
      "type": "boolean",
      "description": "Whether the group is optional. Shows the optional indicator after the group label, unless a surrounding FormLayout already makes fields optional by default.",
      "default": "false"
    },
    {
      "name": "isRequired",
      "type": "boolean",
      "description": "Whether the group needs at least one checked box. Shows the required indicator after the group label by the same rules as every input field. While no box is checked, the browser blocks submit and moves focus to the first box that is neither disabled nor read-only, with its own message. A disabled or read-only group requires nothing. Show your own error text through status. Mutually exclusive with isOptional.",
      "default": "false"
    },
    {
      "name": "density",
      "type": "'compact' | 'balanced' | 'spacious'",
      "description": "Spacing density for list items.",
      "default": "'balanced'"
    },
    {
      "name": "hasDividers",
      "type": "boolean",
      "description": "Whether to show dividers between items.",
      "default": "false"
    },
    {
      "name": "isDisabled",
      "type": "boolean",
      "description": "Whether all checkbox items are disabled.",
      "default": "false"
    },
    {
      "name": "disabledMessage",
      "type": "string",
      "description": "Explains why the group is disabled. Applies to the whole-group disabled state (isDisabled), not per item. With isDisabled, shows a tooltip on hover/keyboard focus and keeps the checkboxes focusable via aria-disabled (toggling stays blocked). Use this instead of wrapping a disabled CheckboxList in Tooltip. Disabled controls swallow the hover events an external Tooltip needs."
    },
    {
      "name": "isReadOnly",
      "type": "boolean",
      "description": "Whether all checkbox items are read-only. Displays the current state at full opacity but prevents interaction. Unlike isDisabled, read-only checkboxes are not visually dimmed.",
      "default": "false"
    },
    {
      "name": "status",
      "type": "{type: 'warning' | 'error' | 'success', message?: string}",
      "description": "Status indicator ({ type, message })."
    },
    {
      "name": "width",
      "type": "SizeValue",
      "description": "Width of the field (number = pixels, string used as-is, e.g. \"100%\"). Sizes the whole field (label, control, and status) so they stay aligned."
    },
    {
      "name": "containerXstyle",
      "type": "StyleXStyles",
      "description": "StyleX styles for the field container (label, control, and status together). No effect inside InputGroup (style the InputGroup instead) or in a `horizontal-labels` FormLayout. Root `xstyle`, `className`, and `style` are not accepted."
    },
    {
      "name": "containerClassName",
      "type": "string",
      "description": "Class name for the field container. Same targeting as `containerXstyle`."
    },
    {
      "name": "containerStyle",
      "type": "CSSProperties",
      "description": "Inline styles for the field container. Same targeting as `containerXstyle`."
    },
    {
      "name": "controlXstyle",
      "type": "StyleXStyles",
      "description": "StyleX styles for the visual control box: the element that paints the border and background and holds icons and end controls. Never the native input."
    },
    {
      "name": "controlClassName",
      "type": "string",
      "description": "Class name for the visual control box."
    },
    {
      "name": "controlStyle",
      "type": "CSSProperties",
      "description": "Inline styles for the visual control box."
    }
  ],
  "meta": {
    "answeredBy": {
      "cli": "0.7.12",
      "core": "0.7.12",
      "copy": "starting"
    }
  }
}
